import math

def sigma(n):
    """Calculates the sum of divisors sigma(n)."""
    if n <= 0:
        return 0
    s = 1
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            p = i
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            s *= (p**(count + 1) - 1) // (p - 1)
        i += 1
    if temp > 1:
        s *= (temp**2 - 1) // (temp - 1)
    return s

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

candidates = []
# Check up to m = 100 as requested to list the first few
for m in range(2, 101):
    s_m = sigma(m)
    if is_square(s_m):
        candidates.append((m, s_m))

print("Candidates m > 1 such that sigma(m) is a perfect square (up to m=100):")
for m, s_m in candidates:
    print(f"m={m}, sigma(m)={s_m}")
